import{REST as o}from"../../shared/js/avatar-figure-1.0.0.min.js";export const MAX_HEAD_TURN=1.1,ARM_POSES=Object.freeze({stand:null,dismiss:Object.freeze({z:.4,x:-1.1,fore:-1.1,twist:Math.PI}),approve:Object.freeze({z:.3,x:-1.9,fore:-.4,twist:0}),present:Object.freeze({z:1.25,x:-.5,fore:-.6,twist:0}),shake:Object.freeze({z:.1,x:-1,fore:-.7,twist:0}),lookBack:null}),HANDSHAKE=Object.freeze({gap:.8,aside:.23,turn:.5}),HEAD_TURNS=Object.freeze({stand:0,dismiss:.45,approve:0,present:.25,shake:0,lookBack:.95}),POSES=Object.freeze(Object.keys(ARM_POSES)),SIDES=Object.freeze(["right","left"]);export function armsFor(n,t="right"){const r=ARM_POSES[n],e={...o};return r?t==="left"?{right:e,left:{...r}}:{right:{...r},left:e}:{right:{...e},left:{...e}}}export function headTurnFor(n,t="right"){const r=s=>Math.max(-MAX_HEAD_TURN,Math.min(MAX_HEAD_TURN,s));if(typeof t=="number")return Number.isFinite(t)?r(t):0;const e=r(Math.max(0,HEAD_TURNS[n]||0));return e===0?0:t==="left"?e:-e}
